import json
from copy import deepcopy

def solve():
    houses = list(range(1, 7))
    names_list = ["Arnold", "Peter", "Carol", "Alice", "Bob", "Eric"]
    children_list = ["Alice", "Timothy", "Bella", "Meredith", "Fred", "Samantha"]
    smoothies_list = ["desert", "cherry", "watermelon", "blueberry", "lime", "dragonfruit"]

    # State
    name_at = {h: None for h in houses}
    child_at = {h: None for h in houses}
    smoothie_at = {h: None for h in houses}

    used_names = set()
    used_children = set()
    used_smoothies = set()

    # Pre-assign from clues:
    # 13. The person's child is named Meredith is in the sixth house.
    # 14. The Dragonfruit smoothie lover is the person's child is named Meredith.
    child_at[6] = "Meredith"
    used_children.add("Meredith")
    smoothie_at[6] = "dragonfruit"
    used_smoothies.add("dragonfruit")

    # Helper functions
    def pos_of(value, arr):
        for h in houses:
            if arr[h] == value:
                return h
        return None

    def check_global_partial():
        # 3. Alice is not in the fifth house.
        if name_at[5] == "Alice":
            return False
        # 4. Samantha not in second house.
        if child_at[2] == "Samantha":
            return False
        # 9. Arnold is not in the second house.
        if name_at[2] == "Arnold":
            return False

        # 11. Arnold is directly left of Carol.
        pa = pos_of("Arnold", name_at)
        pc = pos_of("Carol", name_at)
        if pa is not None and pc is not None:
            if pa + 1 != pc:
                return False
        if pa is not None:
            if pa == 6:
                return False
            # If the right neighbor is assigned and not Carol -> impossible
            if name_at.get(pa + 1) is not None and name_at[pa + 1] != "Carol":
                return False
        if pc is not None:
            if pc == 1:
                return False
            # If the left neighbor is assigned and not Arnold -> impossible
            if name_at.get(pc - 1) is not None and name_at[pc - 1] != "Arnold":
                return False

        # 6. Alice is the person's child is named Alice.
        pa_name = pos_of("Alice", name_at)
        pa_child = pos_of("Alice", child_at)
        if pa_name is not None and pa_child is not None:
            if pa_name != pa_child:
                return False
        if pa_name is not None:
            if child_at[pa_name] is not None and child_at[pa_name] != "Alice":
                return False
        if pa_child is not None:
            if name_at[pa_child] is not None and name_at[pa_child] != "Alice":
                return False

        # 7. Alice is the Watermelon smoothie lover.
        pw = pos_of("watermelon", smoothie_at)
        if pa_name is not None and pw is not None:
            if pa_name != pw:
                return False
        if pa_name is not None:
            if smoothie_at[pa_name] is not None and smoothie_at[pa_name] != "watermelon":
                return False
        if pw is not None:
            if name_at[pw] is not None and name_at[pw] != "Alice":
                return False

        # 10. Bob is the person who is the mother of Timothy.
        pb_name = pos_of("Bob", name_at)
        pt_child = pos_of("Timothy", child_at)
        if pb_name is not None and pt_child is not None:
            if pb_name != pt_child:
                return False
        if pb_name is not None:
            if child_at[pb_name] is not None and child_at[pb_name] != "Timothy":
                return False
        if pt_child is not None:
            if name_at[pt_child] is not None and name_at[pt_child] != "Bob":
                return False

        # 12. Cherry directly left of child Samantha.
        pc_sam = pos_of("Samantha", child_at)
        pch = pos_of("cherry", smoothie_at)
        if pch is not None:
            if pch == 6:
                return False
            # right neighbor child must be Samantha
            if child_at[pch + 1] is not None and child_at[pch + 1] != "Samantha":
                return False
        if pc_sam is not None:
            if pc_sam == 1:
                return False
            if smoothie_at[pc_sam - 1] is not None and smoothie_at[pc_sam - 1] != "cherry":
                return False
        if pch is not None and pc_sam is not None:
            if pch + 1 != pc_sam:
                return False

        # 5. Watermelon right of Cherry.
        if pw is not None and pch is not None:
            if not (pw > pch):
                return False
        if pw is not None:
            if pw == 1:
                return False
        if pch is not None:
            if pch == 6:
                return False

        # 1. Child Fred and Desert smoothie adjacent.
        pf = pos_of("Fred", child_at)
        pd = pos_of("desert", smoothie_at)
        if pf is not None and pd is not None:
            if abs(pf - pd) != 1:
                return False
        if pf is not None:
            # Both neighbors not desert -> invalid
            neighbors = []
            if pf - 1 >= 1:
                neighbors.append(pf - 1)
            if pf + 1 <= 6:
                neighbors.append(pf + 1)
            # if all existing neighbors assigned and none is desert -> invalid
            if len(neighbors) > 0:
                all_assigned = all(smoothie_at[n] is not None for n in neighbors)
                if all_assigned and all(smoothie_at[n] != "desert" for n in neighbors):
                    return False
        if pd is not None:
            neighbors = []
            if pd - 1 >= 1:
                neighbors.append(pd - 1)
            if pd + 1 <= 6:
                neighbors.append(pd + 1)
            if len(neighbors) > 0:
                all_assigned = all(child_at[n] is not None for n in neighbors)
                if all_assigned and all(child_at[n] != "Fred" for n in neighbors):
                    return False

        # 2. Blueberry left of child Fred.
        pb = pos_of("blueberry", smoothie_at)
        if pf is not None and pb is not None:
            if not (pb < pf):
                return False
        if pf is not None:
            if pf == 1:
                return False
            # If all left smoothies assigned and none blueberry -> invalid
            left_positions = list(range(1, pf))
            if left_positions:
                all_assigned = all(smoothie_at[i] is not None for i in left_positions)
                if all_assigned and all(smoothie_at[i] != "blueberry" for i in left_positions):
                    return False
        if pb is not None:
            if pb == 6:
                return False
            # If all right children assigned and none Fred -> invalid
            right_positions = list(range(pb + 1, 7))
            if right_positions:
                all_assigned = all(child_at[i] is not None for i in right_positions)
                if all_assigned and all(child_at[i] != "Fred" for i in right_positions):
                    return False

        # 8. Peter is somewhere to the right of the person's child is named Samantha.
        pp = pos_of("Peter", name_at)
        if pc_sam is not None and pp is not None:
            if not (pp > pc_sam):
                return False
        if pp is not None:
            if pp == 1:
                return False
        if pc_sam is not None:
            if pc_sam == 6:
                return False
            # If all names to the right are assigned and none Peter -> invalid
            right_positions = list(range(pc_sam + 1, 7))
            if right_positions:
                all_assigned = all(name_at[i] is not None for i in right_positions)
                if all_assigned and all(name_at[i] != "Peter" for i in right_positions):
                    return False

        # 7 with 5: watermelon must be to right of cherry already handled partially.

        # 14. Dragonfruit smoothie lover is the person's child is named Meredith.
        # Already enforced by pre-assign, but cross-check:
        pdg = pos_of("dragonfruit", smoothie_at)
        pm = pos_of("Meredith", child_at)
        if pdg is not None and pm is not None and pdg != pm:
            return False

        return True

    def domain_for(var):
        kind, h = var
        if kind == "name":
            dom = [n for n in names_list if n not in used_names]
            # 3. Alice not in house 5
            if h == 5 and "Alice" in dom:
                dom.remove("Alice")
            # 9. Arnold not in house 2
            if h == 2 and "Arnold" in dom:
                dom.remove("Arnold")
            # 11. Arnold left of Carol implications
            # boundary exclusions
            if h == 6 and "Arnold" in dom:
                dom.remove("Arnold")
            if h == 1 and "Carol" in dom:
                dom.remove("Carol")
            # neighbor value dependencies
            if h - 1 >= 1 and name_at[h - 1] is not None:
                if name_at[h - 1] == "Arnold":
                    dom = [x for x in dom if x == "Carol"]
                else:
                    # If left neighbor is not Arnold, Carol cannot be here
                    dom = [x for x in dom if x != "Carol"]
            if h + 1 <= 6 and name_at[h + 1] is not None:
                if name_at[h + 1] == "Carol":
                    dom = [x for x in dom if x == "Arnold"]
                else:
                    # If right neighbor is not Carol, Arnold cannot be here
                    dom = [x for x in dom if x != "Arnold"]

            # Tie-ins with child and smoothie
            if child_at[h] is not None:
                if child_at[h] == "Alice":
                    dom = [x for x in dom if x == "Alice"]
                if child_at[h] != "Timothy":
                    dom = [x for x in dom if x != "Bob"]
                else:
                    dom = [x for x in dom if x in ("Bob",)]
            if smoothie_at[h] is not None:
                if smoothie_at[h] == "watermelon":
                    dom = [x for x in dom if x == "Alice"]
                else:
                    dom = [x for x in dom if x != "Alice"]
            return dom

        if kind == "child":
            dom = [c for c in children_list if c not in used_children]
            # 13: child Meredith is in 6th
            if h == 6:
                dom = [c for c in dom if c == "Meredith"]
            else:
                dom = [c for c in dom if c != "Meredith"]
            # 4. Samantha not in 2nd house
            if h == 2 and "Samantha" in dom:
                dom.remove("Samantha")
            # 12: cherry directly left of child Samantha
            if h - 1 >= 1 and smoothie_at[h - 1] is not None:
                if smoothie_at[h - 1] == "cherry":
                    dom = [c for c in dom if c == "Samantha"]
                else:
                    dom = [c for c in dom if c != "Samantha"]
            if h == 1:
                dom = [c for c in dom if c != "Samantha"]
            # 1: Fred adjacent to desert
            if "Fred" in dom:
                neighbors = []
                if h - 1 >= 1:
                    neighbors.append(h - 1)
                if h + 1 <= 6:
                    neighbors.append(h + 1)
                if not neighbors:
                    dom = [c for c in dom if c != "Fred"]
                else:
                    if all(smoothie_at[n] is not None and smoothie_at[n] != "desert" for n in neighbors):
                        dom = [c for c in dom if c != "Fred"]
            # 2: blueberry left of child Fred
            # If no house to left has possibility of blueberry, remove Fred
            if "Fred" in dom:
                left_positions = list(range(1, h))
                if not left_positions:
                    dom = [c for c in dom if c != "Fred"]
                else:
                    # If all left smoothies assigned and none blueberry -> cannot place Fred here
                    if all(smoothie_at[i] is not None for i in left_positions):
                        if all(smoothie_at[i] != "blueberry" for i in left_positions):
                            dom = [c for c in dom if c != "Fred"]
            # 8: Peter right of Samantha
            if "Samantha" in dom:
                # require some position to the right where name can be Peter
                right_positions = list(range(h + 1, 7))
                if not right_positions:
                    dom = [c for c in dom if c != "Samantha"]
                else:
                    # If all names to the right assigned and none Peter -> cannot be Samantha here
                    if all(name_at[i] is not None for i in right_positions):
                        if all(name_at[i] != "Peter" for i in right_positions):
                            dom = [c for c in dom if c != "Samantha"]
            # Name ties
            if name_at[h] is not None:
                if name_at[h] == "Alice":
                    dom = [c for c in dom if c == "Alice"]
                elif name_at[h] == "Bob":
                    dom = [c for c in dom if c == "Timothy"]
                else:
                    dom = [c for c in dom if c != "Alice" and c != "Timothy"]
            # Smoothie ties
            if smoothie_at[h] is not None:
                if smoothie_at[h] == "dragonfruit":
                    dom = [c for c in dom if c == "Meredith"]
                else:
                    dom = [c for c in dom if c != "Meredith"]
            return dom

        if kind == "smoothie":
            dom = [s for s in smoothies_list if s not in used_smoothies]
            # 14: dragonfruit with Meredith at house 6
            if h == 6:
                dom = [s for s in dom if s == "dragonfruit"]
            else:
                dom = [s for s in dom if s != "dragonfruit"]
            # 12: cherry directly left of Samantha
            if h == 6 and "cherry" in dom:
                dom.remove("cherry")
            if h + 1 <= 6 and child_at[h + 1] is not None:
                if child_at[h + 1] == "Samantha":
                    dom = [s for s in dom if s == "cherry"]
                else:
                    dom = [s for s in dom if s != "cherry"]
            if h == 1 and "cherry" in dom:
                # cherry can be at 1 if Samantha at 2 (not yet assigned), so allow. We'll handle in global check.
                pass
            # 1: desert adjacent to Fred
            if "desert" in dom:
                neighbors = []
                if h - 1 >= 1:
                    neighbors.append(h - 1)
                if h + 1 <= 6:
                    neighbors.append(h + 1)
                if not neighbors:
                    dom = [s for s in dom if s != "desert"]
                else:
                    if all(child_at[n] is not None and child_at[n] != "Fred" for n in neighbors):
                        dom = [s for s in dom if s != "desert"]
            # 2: blueberry left of child Fred
            if "blueberry" in dom:
                right_positions = list(range(h + 1, 7))
                if not right_positions:
                    dom = [s for s in dom if s != "blueberry"]
                else:
                    if all(child_at[i] is not None for i in right_positions):
                        if all(child_at[i] != "Fred" for i in right_positions):
                            dom = [s for s in dom if s != "blueberry"]
            # 5: Watermelon right of Cherry
            # if watermelon at h, ensure possible cherry to left
            if "watermelon" in dom:
                left_positions = list(range(1, h))
                if not left_positions:
                    dom = [s for s in dom if s != "watermelon"]
                else:
                    # If all left smoothies assigned and none cherry -> cannot place watermelon here
                    if all(smoothie_at[i] is not None for i in left_positions):
                        if all(smoothie_at[i] != "cherry" for i in left_positions):
                            dom = [s for s in dom if s != "watermelon"]
            # Name ties
            if name_at[h] is not None:
                if name_at[h] == "Alice":
                    dom = [s for s in dom if s == "watermelon"]
                else:
                    dom = [s for s in dom if s != "watermelon"]
            # Child ties
            if child_at[h] is not None:
                if child_at[h] == "Meredith":
                    dom = [s for s in dom if s == "dragonfruit"]
                else:
                    dom = [s for s in dom if s != "dragonfruit"]
            return dom

        return []

    def select_unassigned_variable():
        variables = []
        for h in houses:
            if name_at[h] is None:
                variables.append(("name", h))
            if child_at[h] is None:
                variables.append(("child", h))
            if smoothie_at[h] is None:
                variables.append(("smoothie", h))
        # MRV heuristic
        best_var = None
        best_dom = None
        best_len = 10**9
        for var in variables:
            d = domain_for(var)
            l = len(d)
            if l < best_len:
                best_len = l
                best_var = var
                best_dom = d
            if l == 0:
                # immediate failure shortcut
                return var, []
        return best_var, best_dom

    def assign(var, val):
        kind, h = var
        if kind == "name":
            name_at[h] = val
            used_names.add(val)
        elif kind == "child":
            child_at[h] = val
            used_children.add(val)
        elif kind == "smoothie":
            smoothie_at[h] = val
            used_smoothies.add(val)

    def unassign(var, val):
        kind, h = var
        if kind == "name":
            name_at[h] = None
            used_names.discard(val)
        elif kind == "child":
            child_at[h] = None
            used_children.discard(val)
        elif kind == "smoothie":
            smoothie_at[h] = None
            used_smoothies.discard(val)

    def is_complete():
        return all(name_at[h] is not None for h in houses) and \
               all(child_at[h] is not None for h in houses) and \
               all(smoothie_at[h] is not None for h in houses)

    def backtrack():
        if not check_global_partial():
            return False
        if is_complete():
            return True
        var, dom = select_unassigned_variable()
        if dom is None or len(dom) == 0:
            return False
        # Try values in domain
        for val in dom:
            assign(var, val)
            if check_global_partial():
                if backtrack():
                    return True
            unassign(var, val)
        return False

    success = backtrack()
    if not success:
        raise RuntimeError("No solution found")

    # Prepare JSON output
    header = ["House", "name", "mother is accompanied by their child", "favorite smoothie"]
    rows = []
    for h in houses:
        rows.append([str(h), name_at[h], child_at[h], smoothie_at[h]])

    result = {
        "solution": {
            "header": header,
            "rows": rows
        }
    }
    return result

if __name__ == "__main__":
    result = solve()
    print(json.dumps(result, ensure_ascii=False, indent=2))
